<template><div class="fixed inset-0 z-[70] flex items-center justify-center bg-black/70 p-4" @click.self="$emit('close')"><form class="w-full max-w-lg space-y-5 rounded-xl border border-gray-700 bg-gray-800 p-6 shadow-2xl" @submit.prevent="submit"><div><h2 class="text-xl font-semibold text-white">{{checkingIn?'Check in':'Check out'}} {{item.name}}</h2><p class="mt-1 font-mono text-sm text-gray-400">{{item.barcode}}</p></div><div v-if="!checkingIn" class="relative"><label class="label">Member</label><input v-model="query" autofocus autocomplete="off" class="field" placeholder="Search name or email" @input="search"><div v-if="results.length" class="absolute z-10 mt-1 max-h-56 w-full overflow-auto rounded-lg border border-gray-600 bg-gray-900 p-1"><button v-for="user in results" :key="user.id" type="button" class="w-full rounded p-3 text-left hover:bg-gray-700" @click="select(user)"><div class="text-white">{{user.displayName||`${user.firstName} ${user.lastName}`}}</div><div class="text-sm text-gray-400">{{user.email}}</div></button></div><p v-if="selected" class="mt-2 text-sm text-green-300">Selected {{selected.displayName||`${selected.firstName} ${selected.lastName}`}} · {{selected.email}}</p></div><div v-else><label class="label">Return bin</label><select v-model="binId" class="field"><option value="">Unassigned</option><option v-for="bin in bins" :key="bin.id" :value="bin.id">{{bin.room?`${bin.room} · `:''}}{{bin.name}}</option></select></div><div><label class="label">Note (optional)</label><textarea v-model="note" maxlength="1000" rows="3" class="field resize-y" placeholder="Add a checkout or check-in note" /></div><div v-if="error" class="rounded bg-red-900/50 p-3 text-red-200">{{error}}</div><div class="flex justify-end gap-2"><button type="button" class="btn bg-gray-700" @click="$emit('close')">Cancel</button><button :disabled="saving||(!checkingIn&&!selected)" class="btn bg-blue-600 disabled:opacity-50">{{saving?'Working…':checkingIn?'Check in item':'Check out item'}}</button></div></form></div></template>
<script setup lang="ts">import{computed,ref}from'vue';import apiService from'@/services/api';import type{InventoryBin,InventoryItem}from'@/types/api';const props=defineProps<{item:InventoryItem;bins:InventoryBin[]}>(),emit=defineEmits<{close:[];saved:[]}>();const checkingIn=computed(()=>!!props.item.checkedOutToId),query=ref(''),results=ref<any[]>([]),selected=ref<any|null>(null),binId=ref(props.item.binId||''),note=ref(''),saving=ref(false),error=ref('');async function search(){selected.value=null;if(query.value.trim().length<2){results.value=[];return}results.value=(await apiService.searchUsers(query.value.trim(),8)).data}function select(user:any){selected.value=user;query.value=user.displayName||`${user.firstName} ${user.lastName}`;results.value=[]}async function submit(){saving.value=true;error.value='';try{await apiService.inventoryTransaction(checkingIn.value?{action:'checkin',barcode:props.item.barcode,binId:binId.value||null,note:note.value.trim()||undefined}:{action:'checkout',barcode:props.item.barcode,memberCode:selected.value.id,note:note.value.trim()||undefined});emit('saved')}catch(e:any){error.value=e.response?.data?.error||'Transaction failed'}finally{saving.value=false}}</script>
<style scoped>.label{@apply mb-2 block text-sm font-medium text-gray-300}.field{@apply w-full rounded-lg border border-gray-600 bg-gray-900 px-4 py-3 text-white}.btn{@apply rounded-lg px-4 py-2 font-medium text-white hover:brightness-110}</style>
